const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const namibia = ee.Geometry.Polygon([
    [[11.734, -17.475], [11.734, -28.969], [25.254, -28.969], [25.254, -17.475]]
  ]);

  const startDate = '2021-01-01';
  const endDate = '2021-01-31';

  // 2. Data Acquisition
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(startDate, endDate)
    .filterBounds(namibia);

  const collectionSize = chirps.size().getInfo();
  console.log(`January 2021 Images: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Calculate total precipitation
  const totalPrecip = chirps.sum();

  // Check for valid pixels
  const pixelCount = totalPrecip.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: namibia,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  console.log(`Valid pixels: ${pixelCount}`);

  if (pixelCount === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Calculation - Get mean precipitation and convert to inches
  const meanPrecip = totalPrecip.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: namibia,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  // Convert mm to inches (1 inch = 25.4 mm)
  const precipInches = meanPrecip / 25.4;

  console.log(`Total rainfall: ${precipInches.toFixed(2)} inches`);

  // 5. Validation & Final Answer
  if (meanPrecip === null || meanPrecip === undefined || !isFinite(meanPrecip)) {
    console.log("<answer>C3</answer>");
  } else if (precipInches > 7) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
